<?php defined('BASEPATH') OR exit('No direct script access allowed');
$e = function ($value) { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); };
$month_start = new DateTimeImmutable($month . '-01');
$month_prev = $month_start->modify('-1 month')->format('Y-m');
$month_next = $month_start->modify('+1 month')->format('Y-m');
$rows = $queue['rows']; $total = (int)$queue['total'];
$pages = max(1, (int)ceil($total / 25));
$ready_count = count($options['ready']); $call_in_count = count($options['call_in']);
?>
