  <?php if ($can_edit && $d >= date('Y-m-d')): ?><?= form_open('team/roster_cover_cancel', array('class'=>'sc-no-print', 'onsubmit'=>"return confirm('Cancel this assignment? The sick Shift will need cover again.');")) ?><input type="hidden" name="cover_id" value="<?= (int)$assigned->id ?>"><input type="hidden" name="user_id" value="<?= (int)$absent->id ?>"><input type="hidden" name="date" value="<?= $d ?>"><label for="scCancelReason" style="font-size:11px;display:block;margin:9px 0 4px">Reason for cancellation</label><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="scCancelReason" class="form-control" name="reason" minlength="5" maxlength="255" required placeholder="E.g. worker unavailable" style="max-width:320px"><button class="btn btn-ghost btn-sm" type="submit">Cancel cover</button></div><?= form_close() ?><?php endif; ?>
<?php else: ?>
  <div class="sc-note">Matching requires the <strong>same site, role and position</strong>, at least the same skill level, and any current certificates held by the absent worker. That certificate comparison is a conservative proxy, not a legal qualification check; the supervisor must still confirm competency, rest and workload. A coworker already on the same Shift can redistribute duties but does not restore headcount. An Off worker requires an explicitly agreed, compensated call-in.</div>
  <div class="sc-summary" aria-label="Candidate summary"><div class="sc-stat"><b><?= $ready_count ?></b><small>On-shift or authorised call-in matches</small></div><div class="sc-stat"><b><?= $call_in_count ?></b><small>Off-day staff requiring call-in</small></div><div class="sc-stat"><b><?= count($options['blocked']) ?></b><small>Unavailable or incompatible candidates</small></div></div>
  <?php if (!$ready_count && !$call_in_count): ?><div class="sc-note warn" role="status"><strong>No safe candidate found.</strong> Do not assign an unavailable worker. Check that profiles have accurate sites, positions and certifications; arrange another qualified person or escalate the staffing gap.</div><?php endif; ?>
