<?php if (!$list): ?><div class="sc-empty">No <?= $category === 'ready' ? 'eligible workers with matching shifts or authorised call-ins' : 'compatible Off-day workers' ?> on this date.</div><?php else: ?><div class="sc-body sc-card-grid">
