<div class="sc-card"><div class="sc-title"><div><strong><?= $e($p->first_name . ' ' . $p->last_name) ?></strong><small><?= $e($p->employee_id) ?> · <?= $e($p->position) ?> · <?= $e($p->site) ?> · <?= $e($p->skill_level) ?></small></div><span class="sc-pill <?= $needs_call ? 'call' : 'ok' ?>"><?= $on_shift ? 'On Shift' : ($needs_call ? 'Off · not available' : 'Off · authorised') ?></span></div>
