<?php if ($can_edit): ?><?= form_open('team/roster_cover_approve') ?><input type="hidden" name="user_id" value="<?= (int)$absent->id ?>"><input type="hidden" name="cover_user_id" value="<?= (int)$p->id ?>"><input type="hidden" name="date" value="<?= $d ?>">
  <?php if ($needs_call): ?><label for="scComp<?= (int)$p->id ?>">Off-day compensation</label><select class="form-select" name="compensation" id="scComp<?= (int)$p->id ?>" required><option value="">Select…</option><option value="TimeOff">Replacement Off day</option><option value="Pay">Overtime via external payroll</option></select>
  <label class="sc-check"><input type="checkbox" name="availability_confirmed" value="1" required> I confirmed this worker agreed to be called in on their Off day.</label>
  <?php elseif (!$on_shift && $entry['extra']): ?><p>Existing authorised compensation: <strong><?= $e($entry['extra']->compensation) ?></strong>. It remains a separate exception and must be confirmed against actual attendance.</p><?php endif; ?>
  <label class="sc-check"><input type="checkbox" name="capacity_checked" value="1" required> I verified this worker's competency, rest, other duties and ability to cover.</label>
  <label for="scReason<?= (int)$p->id ?>">Approval / call-in reason</label><input class="form-control" id="scReason<?= (int)$p->id ?>" name="reason" minlength="5" maxlength="255" required placeholder="E.g. shift coverage agreed with worker">
  <button type="submit" class="btn <?= $needs_call ? 'btn-ghost' : 'btn-primary' ?> btn-sm"><?= $needs_call ? 'Authorise call-in & approve cover' : 'Approve cover' ?></button><?= form_close() ?><?php endif; ?>
</div><?php endforeach; ?></div><?php endif; ?></section><?php endforeach; ?>
