<?php foreach ($rows as $entry): ?><tr><td><?= date('D, d M', strtotime($entry->work_date)) ?></td><td><strong><?= $e($entry->first_name . ' ' . $entry->last_name) ?></strong><br><small><?= $e($entry->employee_id) ?> · <?= $e($entry->site ?: 'Site missing') ?></small></td><td><?= $e($entry->shift_name) ?><br><small><?= substr($entry->start_time,0,5) ?>–<?= substr($entry->end_time,0,5) ?></small></td><td><?php if ($entry->cover_id): ?><span class="sc-pill ok">Covered</span><br><small><?= $e(trim($entry->cover_first_name . ' ' . $entry->cover_last_name)) ?> · <?= $entry->cover_mode === 'OffCallIn' ? 'Off call-in' : 'On Shift' ?></small><?php else: ?><span class="sc-pill urgent">Needs cover</span><?php endif; ?></td><td class="sc-no-print"><a href="<?= site_url('team/roster_cover?user=' . (int)$entry->absent_user_id . '&date=' . $entry->work_date . '&month=' . $month) ?>"><?= $entry->cover_id ? 'Review' : 'Find cover' ?> ↗</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
